import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Where } from '../types'

const POLL_MS = 5000
const BRANCH_COLOR = 'green'
const WORKTREE_COLOR = 'magenta'

const where = atom({ plugin: 'where-am-i', key: 'where' } as const, null)

// /Users/<name>/... and /home/<name>/... read as ~/...
export const tildify = (path: string): string =>
  path.replace(/^\/(Users|home)\/[^/]+(?=\/|$)/, '~')

const basename = (path: string): string =>
  path.replace(/\/+$/, '').split('/').pop() ?? path

// Lines of `git rev-parse --path-format=absolute --git-dir --git-common-dir
// --show-toplevel --abbrev-ref HEAD`; a linked worktree's git dir differs
// from the common one.
export const parseRevParse = (cwd: string, stdout: string): Where => {
  const [gitDir, commonDir, top, ref] = stdout.trim().split('\n')
  if (gitDir === undefined || commonDir === undefined || top === undefined || ref === undefined) {
    return { cwd }
  }
  return {
    cwd,
    branch: ref,
    worktree: gitDir === commonDir ? undefined : basename(top),
  }
}

export type Segment = { text: string; color?: string }

// What the footer shows, left to right: the engine's modes, the directory
// (both dim), then the worktree and the branch in their colors.
export const segments = (here: Where, modes: readonly string[]): Segment[] => [
  ...(modes.length === 0 ? [] : [{ text: `${modes.join(' & ')} · ` }]),
  { text: tildify(here.cwd) },
  ...(here.worktree === undefined ? [] : [{ text: ` ${here.worktree}`, color: WORKTREE_COLOR }]),
  ...(here.branch === undefined ? [] : [{ text: ` ${here.branch}`, color: BRANCH_COLOR }]),
]

const isSame = (a: Where | null, b: Where): boolean =>
  a !== null && a.cwd === b.cwd && a.branch === b.branch && a.worktree === b.worktree

async function locate($: EngineInterface): Promise<Where> {
  const cwd = await $.session.cwd()
  const run = (argv: string[]) => $.process.run(['git', ...argv], { cwd, timeoutMs: 3000 })

  const found = await run([
    'rev-parse', '--path-format=absolute',
    '--git-dir', '--git-common-dir', '--show-toplevel', '--abbrev-ref', 'HEAD',
  ]).catch(() => undefined)
  if (found === undefined || found.exitCode !== 0) return { cwd }

  const located = parseRevParse(cwd, found.stdout)
  if (located.branch !== 'HEAD') return located

  const sha = await run(['rev-parse', '--short', 'HEAD']).catch(() => undefined)
  return { ...located, branch: sha?.exitCode === 0 ? `detached@${sha.stdout.trim()}` : 'detached' }
}

let isRefreshing = false

async function refresh($: EngineInterface): Promise<void> {
  if (isRefreshing) return
  isRefreshing = true
  try {
    const next = await locate($)
    // Writing only on a change keeps the footer from redrawing every poll.
    if (!isSame(await read($, where), next)) await update($, where, () => next)
  } finally {
    isRefreshing = false
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    // 0.1.0 pinned a status line; take it down.
    $.ui.status(undefined)
    void refresh($)
    // Catches a checkout made outside this session (another terminal, an IDE).
    $.clock.every(POLL_MS, () => void refresh($))
    return started
  })

  // A Bash `git switch`, EnterWorktree / ExitWorktree, /cd: show it right away.
  on('tool.call', async ($, e, next) => {
    const result = await next(e)
    void refresh($)
    return result
  })

  on('turn.complete', async ($, e, next) => {
    void refresh($)
    return next(e)
  })

  // The dim labels at the right of the prompt footer: the engine's modes
  // stay, the location follows them.
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const here = await read($, where)
    if (here === null) return next(e)

    const { Box, Text } = $.ui.resolve(e)
    const parts = segments(here, e.props.modes).map(part =>
      part.color === undefined
        ? <Text dimColor>{part.text}</Text>
        : <Text color={part.color}>{part.text}</Text>,
    )

    return <Box flexDirection="row">{parts}</Box>
  })
}

